import React from "react";
import { Composition } from "remotion";
import { VIDEOS } from "./videos.generated";

// One composition per videos/<id>/ folder (registry generated by `npm run gen`), id "oj-<id>", 1080x1920 at 30 fps.
export const RemotionRoot: React.FC = () => (
  <>
    {VIDEOS.map((v) => (
      <Composition key={v.id} id={"oj-" + v.id} component={v.Component} durationInFrames={v.frames} fps={30} width={1080} height={1920} />
    ))}
  </>
);
